//! `levels/ffa_split.lvl` (generated by `scripts/gen_split_level.py`): THE SPLIT, two 198 m brick towers 24 m apart. Pinned: floating
//! (no ground), tall, (almost) totally destructible, brick budget, spawns on a 3D walkable network (ramps, landings, bridges),
//! hook-only places, hook anchors everywhere, supported pickups, engine limits.

use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::level::{is_floating, parse_level_file, LevelBox, LevelFile};
use shinobi_sim::power::PowerKind;
use shinobi_sim::pvp::KILL_PLANE_Y;
use shinobi_sim::rapier3d::prelude::*;
use std::collections::{HashMap, VecDeque};

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_split.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_split.lvl: {e}"))
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld { bodies: RigidBodySet::new(), colliders: ColliderSet::new(), islands: IslandManager::new(), queries: QueryPipeline::new() };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

/// Top face of one box at (x, z) (rolled boxes give their slope).
fn surface_at(b: &LevelBox, x: f32, z: f32) -> Option<f32> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
}

fn d3(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

fn vol(b: &LevelBox) -> f32 {
    8.0 * b.half[0] * b.half[1] * b.half[2]
}

#[test]
fn counts_budgets_and_pedestals() {
    let l = load();
    let n = l.level.boxes.len();
    assert!((800..=1800).contains(&n), "{n} boxes");
    let (mut dv, mut tv, mut perm) = (0.0f32, 0.0f32, 0);
    for b in &l.level.boxes {
        tv += vol(b);
        if b.hp > 0.0 {
            dv += vol(b);
        } else {
            perm += 1;
        }
    }
    assert!(dv / tv >= 0.70, "only {:.0} % of the volume is destructible", 100.0 * dv / tv);
    assert!(perm <= 2 * (l.level.spawns.len() + l.pickups.len()), "{perm} permanent boxes: bedrock only under spawns and pedestals");
    for b in l.level.boxes.iter().filter(|b| b.rot_z == 0.0) {
        let (a, c) = (b.half[0].min(b.half[1]).min(b.half[2]) * 2.0, b.half[0].max(b.half[1]).max(b.half[2]) * 2.0);
        assert!(a >= 1.99, "box {b:?} thinner than 2 m");
        assert!(c <= 24.01, "box {b:?} longer than 24 m");
    }
    assert!((14..=18).contains(&l.level.spawns.len()), "{} spawns", l.level.spawns.len());
    let cubes = l.pickups.iter().filter(|p| p.kind == PowerKind::None).count();
    let yumi = l.pickups.iter().filter(|p| p.kind == PowerKind::Yumi).count();
    let tags = l.pickups.iter().filter(|p| p.kind == PowerKind::Tag).count();
    assert_eq!((cubes, yumi, tags), (6, 2, 4), "cubes, bows, tag bags");
    assert!(l.pickups.iter().filter(|p| p.kind != PowerKind::None).all(|p| p.respawn_secs == 45.0));
    assert!(l.pickups.iter().filter(|p| p.kind == PowerKind::Yumi).all(|p| p.pos[1] > 200.0), "bows sit on the rooftops");
    assert!(l.pickups.iter().filter(|p| p.kind == PowerKind::Tag).all(|p| p.pos[1] > 40.0 && p.pos[1] < 160.0), "tag bags sit on the mid bridges");
    // five or more distinct spawn heights
    let mut bands: Vec<i32> = l.level.spawns.iter().map(|s| (s[1] / 12.0).round() as i32).collect();
    bands.sort();
    bands.dedup();
    assert!(bands.len() >= 5, "spawn heights {bands:?}");
}

#[test]
fn it_floats_the_kill_plane_is_far_below_and_the_towers_are_190_m_tall() {
    let l = load();
    assert!(is_floating(&l.level), "no box may reach down toward y = 0");
    let lowest = l.level.boxes.iter().map(|b| b.center[1] - b.half[1]).fold(f32::MAX, f32::min);
    assert!(lowest >= 8.0 - 0.01 && lowest - KILL_PLANE_Y >= 26.0, "lowest body y = {lowest}, kill plane {KILL_PLANE_Y}");
    assert_eq!(l.level.floor_half(), None, "no floor slab");
    let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
    assert!(top - lowest >= 190.0, "tallest geometry spans {} m", top - lowest);
    // two towers: facade bricks on both sides of a canyon 24 m wide
    for s in [-1.0f32, 1.0] {
        let n = l.level.boxes.iter().filter(|b| b.rot_z == 0.0 && (b.center[2] - s * 13.0).abs() < 0.01 && b.half[2] == 1.0 && b.half[1] * 2.0 >= 5.9).count();
        assert!(n >= 150, "{n} facade bricks on side {s}");
    }
    assert!(!l.level.boxes.iter().any(|b| b.rot_z == 0.0 && b.center[2].abs() + b.half[2] < 12.0 && b.half[0] > 14.0), "canyon is blocked by a wide box");
}

#[test]
fn spawns_stand_on_a_deck_clear_of_geometry_and_not_stacked() {
    let l = load();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for s in &l.level.spawns {
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(!l.level.boxes.iter().any(|b| inside(b, p)), "spawn {s:?}: capsule point {p:?} is inside geometry");
            }
        }
        // standing on a flat top, and the plinth is bedrock
        let ok = l.level.boxes.iter().any(|b| b.rot_z == 0.0 && surface_at(b, s[0], s[2]).map_or(false, |h| (h - (s[1] - reach)).abs() < 0.05));
        assert!(ok, "spawn {s:?} floats or is buried");
        assert!(l.level.boxes.iter().any(|b| b.hp == 0.0 && surface_at(b, s[0], s[2]).map_or(false, |h| (h - (s[1] - reach)).abs() < 0.05)), "spawn {s:?} has no permanent plinth");
    }
    let n = l.level.spawns.len();
    let nearest: Vec<f32> = (0..n).map(|i| (0..n).filter(|j| *j != i).map(|j| d3(l.level.spawns[i], l.level.spawns[j])).fold(f32::MAX, f32::min)).collect();
    let min = nearest.iter().copied().fold(f32::MAX, f32::min);
    assert!(min >= 9.0, "two spawns only {min:.1} m apart");
}

type Cell = (i32, i32);

/// 3D walkable network. Node = (cell, surface index): every upward surface at the cell centre with 2.2 m of headroom.
/// Neighbouring cells connect when the surfaces differ by <= 0.5 m (ramps climb 0.4 m per metre).
struct Net {
    surf: HashMap<Cell, Vec<f32>>,
    seen: HashMap<(Cell, usize), ()>,
}

fn surfaces(l: &LevelFile) -> HashMap<Cell, Vec<f32>> {
    // per cell: (top, bottom) of every box over the cell centre
    let mut cols: HashMap<Cell, Vec<(f32, f32)>> = HashMap::new();
    for b in &l.level.boxes {
        let (s, c) = b.rot_z.sin_cos();
        let ex = c.abs() * b.half[0] + s.abs() * b.half[1];
        for x in ((b.center[0] - ex).floor() as i32)..=((b.center[0] + ex).ceil() as i32) {
            for z in ((b.center[2] - b.half[2]).floor() as i32)..=((b.center[2] + b.half[2]).ceil() as i32) {
                if let Some(t) = surface_at(b, x as f32 + 0.5, z as f32 + 0.5) {
                    let bot = t - 2.0 * b.half[1] / c;
                    cols.entry((x, z)).or_default().push((t, bot));
                }
            }
        }
    }
    let mut out = HashMap::new();
    for (cell, v) in cols {
        let mut ys: Vec<f32> = Vec::new();
        for &(t, _) in &v {
            if v.iter().any(|&(t2, b2)| t2 > t + 0.05 && b2 < t + 2.2) {
                continue; // something low overhead
            }
            if ys.iter().any(|y| (y - t).abs() < 0.05) {
                continue;
            }
            ys.push(t);
        }
        out.insert(cell, ys);
    }
    out
}

fn flood(l: &LevelFile) -> Net {
    let surf = surfaces(l);
    let cell_of = |p: [f32; 3]| (p[0].floor() as i32, p[2].floor() as i32);
    let reach = Cfg::default().half_height + Cfg::default().radius;
    let sp = l.level.spawns[0];
    let c0 = cell_of(sp);
    let i0 = surf[&c0].iter().position(|y| (y - (sp[1] - reach)).abs() < 0.1).expect("spawn 0 surface");
    let mut seen = HashMap::new();
    let mut q = VecDeque::from([(c0, i0)]);
    seen.insert((c0, i0), ());
    while let Some((c, i)) = q.pop_front() {
        let y = surf[&c][i];
        for (dx, dz) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let n = (c.0 + dx, c.1 + dz);
            if let Some(ys) = surf.get(&n) {
                for (j, ny) in ys.iter().enumerate() {
                    if (ny - y).abs() <= 0.5 && !seen.contains_key(&(n, j)) {
                        seen.insert((n, j), ());
                        q.push_back((n, j));
                    }
                }
            }
        }
    }
    Net { surf, seen }
}

/// Every spawn walks to every other: the 17 floors of two towers, the bridges and both rooftops are ONE network.
#[test]
fn one_walkable_network_joins_every_spawn_floor_bridge_and_roof() {
    let l = load();
    let net = flood(&l);
    let reach = Cfg::default().half_height + Cfg::default().radius;
    for s in &l.level.spawns {
        let c = (s[0].floor() as i32, s[2].floor() as i32);
        let ok = net.surf.get(&c).map_or(false, |ys| ys.iter().enumerate().any(|(j, y)| (y - (s[1] - reach)).abs() < 0.1 && net.seen.contains_key(&(c, j))));
        assert!(ok, "spawn {s:?} cannot walk to the rest of the map");
    }
    // floors reachable on foot in each tower (z < 0 and z > 0): a floor per 12 m
    let mut floors = [Vec::new(), Vec::new()];
    for (c, j) in net.seen.keys() {
        let y = net.surf[c][*j];
        let side = if c.1 < 0 { 0 } else { 1 };
        let k = ((y - 10.0) / 12.0).round();
        if (y - (10.0 + 12.0 * k)).abs() < 0.01 && c.1.abs() >= 14 && k <= 16.0 {
            floors[side].push(k as i32);
        }
    }
    for (side, f) in floors.iter_mut().enumerate() {
        f.sort();
        f.dedup();
        assert_eq!(f.len(), 17, "tower {side}: floors reachable on foot {f:?}");
    }
    let mut bridges: Vec<i32> = net
        .seen
        .keys()
        .filter(|(c, _)| c.1.abs() <= 10)
        .map(|(c, j)| (net.surf[c][*j] - 10.0) / 12.0)
        .filter(|k| (k - k.round()).abs() < 0.001)
        .map(|k| k.round() as i32)
        .collect();
    bridges.sort();
    bridges.dedup();
    assert!(bridges.len() >= 10, "bridge levels walkable over the canyon: {bridges:?}");
    // hook / wall-run only places: lots of surface, not on the network
    let off = net.surf.iter().filter(|(c, ys)| c.1.abs() <= 10 && ys.iter().enumerate().any(|(j, _)| !net.seen.contains_key(&(**c, j)))).count();
    assert!(off >= 60, "only {off} hook-only canyon cells (gondolas, girders, crane)");
    let crane = net.surf.iter().any(|(c, ys)| ys.iter().enumerate().any(|(j, y)| *y > 225.0 && !net.seen.contains_key(&(*c, j))));
    assert!(crane, "the crane cab must be hook-only");
    // bows: one on the walkable network (north gantry), one hook-only (crane)
    let on_net = |p: [f32; 3]| {
        let c = (p[0].floor() as i32, p[2].floor() as i32);
        net.surf.get(&c).map_or(false, |ys| ys.iter().enumerate().any(|(j, y)| (y - (p[1] - 1.0)).abs() < 0.1 && net.seen.contains_key(&(c, j))))
    };
    let bows: Vec<bool> = l.pickups.iter().filter(|p| p.kind == PowerKind::Yumi).map(|p| on_net(p.pos)).collect();
    assert_eq!(bows.iter().filter(|b| **b).count(), 1, "one bow walkable, one hook-only: {bows:?}");
}

/// Hook anchors: from every spawn and from a sample of the walkable network at least 3 canyon boxes (bridges, balconies, gondolas,
/// counterweights, girders, stays) within 30 m.
#[test]
fn there_are_hook_anchors_within_30_m_of_anywhere() {
    let l = load();
    let net = flood(&l);
    let anchors: Vec<&LevelBox> = l.level.boxes.iter().filter(|b| b.center[2].abs() < 12.5 || b.center[1] > 207.0 || (b.center[2].abs() > 30.0 && b.half[2] >= 3.9)).collect();
    // distance to the nearest point of the box (rolled boxes by their bounding extents)
    let near = |b: &LevelBox, p: [f32; 3]| {
        let (s, c) = b.rot_z.sin_cos();
        let e = [c.abs() * b.half[0] + s.abs() * b.half[1], s.abs() * b.half[0] + c.abs() * b.half[1], b.half[2]];
        let d: Vec<f32> = (0..3).map(|i| ((p[i] - b.center[i]).abs() - e[i]).max(0.0)).collect();
        (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt()
    };
    let count = |p: [f32; 3]| anchors.iter().filter(|b| near(b, p) <= 30.0).count();
    for s in &l.level.spawns {
        assert!(count(*s) >= 3, "spawn {s:?}: only {} anchors in reach", count(*s));
    }
    let mut worst = (usize::MAX, [0.0f32; 3]);
    for (c, j) in net.seen.keys() {
        if c.0.rem_euclid(5) != 0 || c.1.rem_euclid(5) != 0 {
            continue;
        }
        let p = [c.0 as f32 + 0.5, net.surf[c][*j] + 1.0, c.1 as f32 + 0.5];
        let k = count(p);
        if k < worst.0 {
            worst = (k, p);
        }
    }
    assert!(worst.0 >= 3, "only {} anchors within 30 m of {:?}", worst.0, worst.1);
}

#[test]
fn pickups_are_supported_and_not_inside_geometry() {
    let l = load();
    for p in &l.pickups {
        assert!(!l.level.boxes.iter().any(|b| inside(b, p.pos)), "pickup {:?} is inside geometry", p.pos);
        let supported = l.level.boxes.iter().any(|b| surface_at(b, p.pos[0], p.pos[2]).map_or(false, |h| (p.pos[1] - h - 1.0).abs() < 0.3));
        assert!(supported, "pickup {:?} is not ~1 m above a surface", p.pos);
        let perm = l.level.boxes.iter().any(|b| b.hp == 0.0 && surface_at(b, p.pos[0], p.pos[2]).map_or(false, |h| (p.pos[1] - h - 1.0).abs() < 0.3));
        assert!(perm, "pickup {:?} has no permanent plinth", p.pos);
    }
}

#[test]
fn engine_numeric_limits_cover_the_map() {
    let l = load();
    let far = l.level.boxes.iter().map(|b| b.center[0].abs() + b.half[0]).chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2])).fold(0.0, f32::max);
    assert!(far <= 125.0, "geometry reaches {far} m sideways");
    let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
    let q = shinobi_proto::quant::q_pos3([2.0 * far, top + 10.0, 2.0 * far]);
    let back = shinobi_proto::quant::dq_pos3(q);
    assert!((back[0] - 2.0 * far).abs() < 0.01 && (back[1] - (top + 10.0)).abs() < 0.01, "q_pos3 loses precision");
    let w = world(&l);
    assert_eq!(w.colliders.len(), l.level.boxes.len());
}
